  duration
  aspectRatio
  __typename
}

fragment HOME_COLLECTION_FRAGMENT on Collection {
  id
  xid
  name
  stats {
    id
    videos {
      id
      total
      __typename
    }
    __typename
  }
  videos {
    edges {
      node {
        id
        __typename
        ... on Media {
          ...HOME_VIDEO_FRAGMENT
          __typename
        }
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment HOME_POLL_FRAGMENT on Poll {
  id
  question
  options {
    id
    text
    voterCount
    __typename
  }
  voterCount
  component {
    __typename
    ...HOME_COLLECTION_FRAGMENT
  }
  __typename
}

query NEW_HOME_QUERY {
  home: views {
    id
    neon {
      id
      sections(space: "home") {
        edges {
          node {
            id
            name
            title
            description
            groupingType
            components {
              edges {
                node {
                  __typename
                  ... on Media {
                    __typename
                    ...HOME_VIDEO_FRAGMENT
                  }
                  ...HOME_POLL_FRAGMENT
                }
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
"}

