{"operationName":"CHANNEL_VIDEOS_QUERY","variables":{"channel_name":"cinemaforchange","sort":"recent","page":1,"allowExplicit":false},"query":"query CHANNEL_VIDEOS_QUERY($channel_name: String!, $sort: String, $page: Int!, $allowExplicit: Boolean) {
  channel(name: $channel_name) {
    id
    xid
    channel_videos_all_videos: videos(
      sort: $sort
      page: $page
      first: 30
      allowExplicit: $allowExplicit
    ) {
      pageInfo {
        hasNextPage
        nextPage
        __typename
      }
      edges {
        node {
          id
          xid
          title
          thumbnailx60: thumbnailURL(size: "x60")
          thumbnailx120: thumbnailURL(size: "x120")
          thumbnailx240: thumbnailURL(size: "x240")
          thumbnailx720: thumbnailURL(size: "x720")
          bestAvailableQuality
          duration
          createdAt
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
"}

