query SEACH_DISCOVERY_QUERY($shouldQueryPromotedHashtag: Boolean!) {
  home: views {
    id
    neon {
      id
      sections(space: "home") {
        edges {
          node {
            id
            name
            title
            description
            components {
              edges {
                node {
                  __typename
                  ... on Media {
                    __typename
                    ...SEARCH_DISCOVERY_VIDEO_FRAGMENT
                  }
                }
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  featuredContent {
    id
    channels(first: 10) {
      edges {
        node {
          id
          xid
          displayName
          name
          accountType
          logoURL(size: "x120")
          isFollowed
          stats {
            id
            followers {
              id
              total
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  conversations(
    filter: {story: {eq: HASHTAG}, algorithm: {eq: SPONSORED}}
    first: 1
  ) @include(if: $shouldQueryPromotedHashtag) {
    edges {
      node {
        id
        story {
          ... on Hashtag {
            id
            name
            __typename
          }
          __typename
        }
        dailymotionAd {
          id
          channel {
            id
            name
            avatar(height: SQUARE_120) {
              id
              url
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
"}

